class Component extends DCLogic {
  state = { ready: false };
  componentDidMount() { this.tick(); }
  componentWillUnmount() { clearTimeout(this._t); }
  tick() {
    const ok = window.AHV_CAMPAIGN_NINE && window.AHV_CAMPAIGN_NINE_RENDER && window.AHV_COLLECTION_RENDER;
    if (ok) {
      const N = window.AHV_CAMPAIGN_NINE_RENDER;
      const R = N.resolveRoute(this.props.route);
      // Both paths get a head. A miss used to leave the document with no title and no lang at all.
      if (R) N.applyHead(R); else N.applyNotFoundHead(this.requestedRoute());
      this.setState({ ready: true });
      return;
    }
    this._t = setTimeout(() => this.tick(), 60);
  }
  componentDidUpdate(prev) {
    const N = window.AHV_CAMPAIGN_NINE_RENDER;
    if (N && this.state.ready && prev.route !== this.props.route) {
      const R = N.resolveRoute(this.props.route);
      if (R) N.applyHead(R); else N.applyNotFoundHead(this.requestedRoute());
    }
  }
  requestedRoute() {
    let q = null;
    try { q = new URLSearchParams(location.search).get('route'); } catch (e) {}
    return q || this.props.route || '';
  }
  renderVals() {
    const N = window.AHV_CAMPAIGN_NINE_RENDER;
    // The same key set on every path, so nothing renders as an unresolved hole while the data loads.
    if (!this.state.ready || !N || !N.emptyVals) return { path: '', indexable: '', blockCount: '0', imageCount: '0', flags: [], h1El: null, bodyEl: null, formEl: null, canonical: '', robots: '', layoutFit: '', headingDecision: '', title: '', hasForm: false, route: null, notFound: false, found: false, requestedRoute: '', validRoutes: [], showBreadcrumb: false, crumbs: [], crumbLast: '', guard: (e) => { if (e && e.preventDefault) e.preventDefault(); } };
    const R = N.resolveRoute(this.props.route);
    // A requested-but-unknown route gets a visible state naming it and the valid set — never a blank page,
    // and never an unrelated record silently substituted.
    if (!R) return N.notFoundVals(this.requestedRoute());
    // Review-only link guard: every source destination is kept and shown, nothing navigates or posts.
    const guard = () => {}; /* preview-only navigation guard neutralised for the published site: all 91 anchors it is bound to carry real destinations */
    return N.nineVals(R, guard, 'wide');
  }
}
